/// @brief Enumeration for device's error code.
/// @since_tizen 2.3
abstract class device_error_e {
  /// < Successful
  static const int DEVICE_ERROR_NONE = 0;

  /// < Operation not permitted
  static const int DEVICE_ERROR_OPERATION_FAILED = -1;

  /// < Permission denied
  static const int DEVICE_ERROR_PERMISSION_DENIED = -13;

  /// < Invalid parameter
  static const int DEVICE_ERROR_INVALID_PARAMETER = -22;

  /// < Operation already in progress
  static const int DEVICE_ERROR_ALREADY_IN_PROGRESS = -114;

  /// < Not supported in this device
  static const int DEVICE_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Device or resource busy
  static const int DEVICE_ERROR_RESOURCE_BUSY = -16;

  /// < Not initialized
  static const int DEVICE_ERROR_NOT_INITIALIZED = -37748717;
}

/// @brief Enumeration for the battery level status.
/// @since_tizen 2.3
abstract class device_battery_level_e {
  /// < The battery goes empty. Prepare for the safe termination of the application, because the device starts a shutdown process soon after entering this level.
  static const int DEVICE_BATTERY_LEVEL_EMPTY = 0;

  /// < The battery charge is at a critical state. You may have to stop using multimedia features, because they are not guaranteed to work correctly at this battery status.
  static const int DEVICE_BATTERY_LEVEL_CRITICAL = 1;

  /// < The battery has little charge left.
  static const int DEVICE_BATTERY_LEVEL_LOW = 2;

  /// < The battery status is not to be careful.
  static const int DEVICE_BATTERY_LEVEL_HIGH = 3;

  /// < The battery status is fully charged. It means no more charge.
  static const int DEVICE_BATTERY_LEVEL_FULL = 4;
}

/// @brief Enumeration for battery health information.
/// @since_tizen 3.0
abstract class device_battery_health_e {
  /// < The battery health is good
  static const int DEVICE_BATTERY_HEALTH_GOOD = 0;

  /// < The temperature of the battery is cold
  static const int DEVICE_BATTERY_HEALTH_COLD = 1;

  /// < The battery is dead
  static const int DEVICE_BATTERY_HEALTH_DEAD = 2;

  /// < The temperature of the battery is high
  static const int DEVICE_BATTERY_HEALTH_OVER_HEAT = 3;

  /// < The battery is in over voltage state
  static const int DEVICE_BATTERY_HEALTH_OVER_VOLTAGE = 4;
}

/// @brief Enumeration for power source information.
/// @since_tizen 3.0
abstract class device_battery_power_source_e {
  /// < There is no power source
  static const int DEVICE_BATTERY_POWER_SOURCE_NONE = 0;

  /// < AC power cable is connected
  static const int DEVICE_BATTERY_POWER_SOURCE_AC = 1;

  /// < USB power cable is connected
  static const int DEVICE_BATTERY_POWER_SOURCE_USB = 2;

  /// < Power is provided by a wireless source
  static const int DEVICE_BATTERY_POWER_SOURCE_WIRELESS = 3;
}

/// @brief Enumeration for battery property information.
/// @since_tizen 3.0
/// @remarks If the fuel gauge hardware does not provide average current or average voltage,
/// CURRENT_AVERAGE/VOLTAGE_AVERAGE can be substituted by CURRENT_NOW/VOLTAGE_NOW, respectively.
abstract class device_battery_property_e {
  /// < The battery capacity (0 ~ 100 %)
  static const int DEVICE_BATTERY_PROPERTY_CAPACITY = 0;

  /// < The battery current (uA)
  static const int DEVICE_BATTERY_PROPERTY_CURRENT_NOW = 1;

  /// < The average battery current (uA)
  static const int DEVICE_BATTERY_PROPERTY_CURRENT_AVERAGE = 2;

  /// < The battery voltage (uV) (Since 5.0)
  static const int DEVICE_BATTERY_PROPERTY_VOLTAGE_NOW = 3;

  /// < The average battery voltage (uV) (Since 5.0)
  static const int DEVICE_BATTERY_PROPERTY_VOLTAGE_AVERAGE = 4;

  /// < The battery temperature (`C) (Since 5.0)
  static const int DEVICE_BATTERY_PROPERTY_TEMPERATURE = 5;
}

/// @brief Enumeration for battery status information.
/// @since_tizen 3.0
abstract class device_battery_status_e {
  /// < Battery is charging
  static const int DEVICE_BATTERY_STATUS_CHARGING = 0;

  /// < Battery is discharging
  static const int DEVICE_BATTERY_STATUS_DISCHARGING = 1;

  /// < Battery is fully charged
  static const int DEVICE_BATTERY_STATUS_FULL = 2;

  /// < Battery is not charging
  static const int DEVICE_BATTERY_STATUS_NOT_CHARGING = 3;
}

/// @brief Enumeration for the device state callback.
